                  (CUIScreenUnitConverter::GetBackBufferHeight() * 0.5f) - CManager::GetInstance()->GetUIScale().Y * 52.0f);
    PSaveInProgress->ChangePosition(pos, 0.0f, false);
    SaveInProgressTime = GFGetTime();
}

